test_ops:
#include "rt.h"
#include "dps310.h"

#define DPS_ADDR 0x77

void op_main(void)
{
    long tr, pr, tmc, ppa, tmc2, ppa2, dt, dp;
    int e;

    e = dps310_read_raw(DPS_ADDR, &tr, &pr);
    if (e) { fail("dps310 raw read failed"); return; }
    e = dps310_compensate(DPS_ADDR, tr, pr, &tmc, &ppa);
    if (e) { fail("dps310 coefficient read failed"); return; }

    report_int("temp_raw", tr);
    report_int("press_raw", pr);
    report_int("temp_mc", tmc);
    report_int("press_pa", ppa);

    /* the one-call path a sentence op uses must agree with the explicit path */
    e = dps310_read(DPS_ADDR, &tmc2, &ppa2);
    if (e) { fail("dps310_read failed"); return; }
    dt = tmc2 - tmc; if (dt < 0) dt = -dt;
    dp = ppa2 - ppa; if (dp < 0) dp = -dp;
    if (dt > 2000 || dp > 300) { fail("dps310_read disagrees with raw+compensate"); return; }

    if (tmc < -40000 || tmc > 85000) { fail("temperature out of sensor range"); return; }
    if (ppa < 30000 || ppa > 120000) { fail("pressure out of sensor range"); return; }

    report_fixed("temp_c", tmc, 3);
    report_fixed("press_hpa", ppa, 2);
    say("dps310 ok");
}
